-- Account contacts from "FCB Account Emails 1.xlsx" + distributor contacts
-- (2026-11-24, per Chad: "can we update all these accounts in the app if they are
-- missing any of these contacts. Can we also add a contacts button in each
-- distributor, that shows first, the distributor contacts, then the account
-- contacts"). Source: claude/account-contacts-source-2026-11-24.md.
--
-- Part 1: distributor_contacts — a distributor's own people (name, title, phone,
--   email, notes). Shown first in the Contacts pop-up on each distributor page;
--   anyone who can see that distributor's page can add / edit / remove them.
--   Starts with Matagrano's people from the sheet's "Personnel" section.
-- Part 2: distributor_account_contacts(dist) — every contact on that distributor's
--   accounts, for the same pop-up.
-- Part 3: loads the sheet's contacts into Sales → Accounts contacts
--   (sales_account_contacts, source 'FCB Account Emails'), ONLY where missing:
--   * Matched to an account by VIP outlet ID when the app's name (first 4 letters)
--     or city agrees. The on-premise Markstein block (sheet rows 44–112) has its IDs
--     shifted one row, so there the ID only counts when the name agrees; otherwise
--     name + city (or street address + city) is used.
--   * Not added again if that account already has a contact with the same email.
--     If it has the same person with no email, the email is filled in.
--   * The same email twice for one account (CRM Export + KARMA) goes in once.
--   * Rows with no account (Mark's List email-only rows), accounts not in the app,
--     and rows that fit more than one account are skipped and listed at the end.
-- Nothing existing is deleted or changed except blank emails filled in.
-- Run this in Supabase's SQL Editor BEFORE pushing the code. Safe to run more than
-- once (a second run adds nothing). Ends with a summary.

-- ---------------------------------------------------------------------------
-- Part 1: distributor contacts
-- ---------------------------------------------------------------------------
create table if not exists public.distributor_contacts (
  id uuid primary key default gen_random_uuid(),
  distributor text not null,
  name text,
  title text,
  phone text,
  email text,
  notes text,
  sort integer not null default 0,
  created_at timestamptz not null default now(),
  created_by uuid default auth.uid(),
  updated_at timestamptz not null default now()
);
create index if not exists distributor_contacts_dist_idx on public.distributor_contacts (distributor);
alter table public.distributor_contacts enable row level security;
drop policy if exists "distributor_contacts_select" on public.distributor_contacts;
create policy "distributor_contacts_select" on public.distributor_contacts for select using (public.sales_can_see(array[distributor]));
drop policy if exists "distributor_contacts_insert" on public.distributor_contacts;
create policy "distributor_contacts_insert" on public.distributor_contacts for insert with check (public.sales_can_see(array[distributor]));
drop policy if exists "distributor_contacts_update" on public.distributor_contacts;
create policy "distributor_contacts_update" on public.distributor_contacts for update using (public.sales_can_see(array[distributor])) with check (public.sales_can_see(array[distributor]));
drop policy if exists "distributor_contacts_delete" on public.distributor_contacts;
create policy "distributor_contacts_delete" on public.distributor_contacts for delete using (public.sales_can_see(array[distributor]));
grant select, insert, update, delete on public.distributor_contacts to authenticated;
grant select, insert, update, delete on public.distributor_contacts to service_role;
comment on table public.distributor_contacts is
  'People at each distributor (the distributor''s own staff — reps, managers, buyers, office): name, title, phone, email, notes. Shown first in the Contacts pop-up on Distributors → <distributor>, where anyone with that page can add / edit / remove them. Use for "who do we call at Matagrano", "Markstein''s sales manager''s email".';

-- Realtime, so an open pop-up shows edits made by someone else.
do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'distributor_contacts') then
    alter publication supabase_realtime add table public.distributor_contacts;
  end if;
exception when undefined_object then null;
end $$;

-- Matagrano's people from the sheet ("Personnel" section), added once.
select v.d, v.n, v.notes, v.e, v.s, null from (values
  ('Matagrano', 'Shelly McKissick', 'Matagrano staff (25858 Clawiter Rd, Hayward)', 'shellym@matagrano.com', 1),
  ('Matagrano', 'Mike Bisda', 'Matagrano staff (25858 Clawiter Rd, Hayward)', 'mikeb@matagrano.com', 2),
  ('Matagrano', 'Michael Wong', 'Matagrano staff (25858 Clawiter Rd, Hayward)', 'Michaelw@matagrano.com', 3),
  ('Matagrano', 'Anthony Mittieri', 'Matagrano staff (25858 Clawiter Rd, Hayward)', 'anthonym@matagrano.com', 4),
  ('Matagrano', 'Ismael Sifuentes', 'Matagrano staff (25858 Clawiter Rd, Hayward)', 'ismaels@matagrano.com', 5),
  ('Matagrano', 'Dan Silberstein', 'Listed under Matagrano distributor visit', 'dansilberstein1103@gmail.com', 6)
) as v(d, n, notes, e, s)
where not exists (select 1 from public.distributor_contacts c where c.distributor = v.d and lower(trim(c.email)) = lower(trim(v.e)));

-- ---------------------------------------------------------------------------
-- Part 2: every contact on one distributor's accounts (pop-up, below the
-- distributor's own people). Turned-off accounts left out.
-- ---------------------------------------------------------------------------
create or replace function public.distributor_account_contacts(p_dist text)
returns json
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.sales_can_see(array[p_dist]) then
    raise exception 'You don''t have access to this distributor.';
  end if;
  return (select coalesce(json_agg(x order by x.account, x.name nulls last), '[]'::json) from (
    select a.outlet_id, a.name as account, a.city, a.premise, a.last_buy_date as last_buy,
      c.name, c.title, c.phone, c.mobile, c.email, c.source
    from public.sales_account_contacts c
    join public.sales_accounts a on a.outlet_id = c.outlet_id
    where a.distributor = p_dist
      and not exists (select 1 from public.sales_account_off o where o.outlet_id = a.outlet_id)
      and (coalesce(trim(c.name), '') <> '' or coalesce(trim(c.email), '') <> '' or coalesce(trim(c.phone), '') <> '' or coalesce(trim(c.mobile), '') <> '')) x);
end;
$$;
revoke all on function public.distributor_account_contacts(text) from public, anon;
grant execute on function public.distributor_account_contacts(text) to authenticated;
comment on function public.distributor_account_contacts(text) is
  $c$[needs:sales_dashboard] Every contact (name, title, phone, mobile, email, source) on one distributor's accounts, with the account name, city, premise and last buy. Also open to people with that distributor's page.$c$;

-- ---------------------------------------------------------------------------
-- Part 3: account contacts from the sheet
-- ---------------------------------------------------------------------------
drop table if exists pg_temp._ae_rows;
create temp table _ae_rows (i int, grp text, vip text, acct text, addr text, city text, src text, name text, email text);

drop table if exists pg_temp._ae_match;
create temp table _ae_match as
with nn as (
  select r.*,
    regexp_replace(regexp_replace(upper(coalesce(r.acct, '')), '[^A-Z0-9]', '', 'g'), '^THE|THE$', '', 'g') as na,
    regexp_replace(upper(coalesce(r.city, '')), '[^A-Z]', '', 'g') as nc,
    regexp_replace(upper(coalesce(r.addr, '')), '[^A-Z0-9]', '', 'g') as nd,
    (r.i between 44 and 112) as id_suspect
  from _ae_rows r
),
a as (
  select x.outlet_id, x.distributor,
    regexp_replace(regexp_replace(upper(coalesce(x.name, '')), '[^A-Z0-9]', '', 'g'), '^THE|THE$', '', 'g') as na,
    regexp_replace(upper(coalesce(x.city, '')), '[^A-Z]', '', 'g') as nc,
    regexp_replace(upper(coalesce(x.address, '')), '[^A-Z0-9]', '', 'g') as nd
  from public.sales_accounts x
),
cand as (
  -- 1: VIP ID, and the name agrees
  select nn.i, a.outlet_id, a.distributor, 1 as rank from nn join a on a.outlet_id = nn.vip
    where nn.na <> '' and left(a.na, 4) = left(nn.na, 4)
  union all
  -- 2: VIP ID, and the city agrees (not in the shifted block)
  select nn.i, a.outlet_id, a.distributor, 2 from nn join a on a.outlet_id = nn.vip
    where not nn.id_suspect and nn.nc <> '' and a.nc = nn.nc
  union all
  -- 3: name (or street address) + city
  select nn.i, a.outlet_id, a.distributor, 3 from nn join a on a.nc = nn.nc and nn.nc <> ''
    where (length(nn.na) >= 4 and (a.na = nn.na or a.na like nn.na || '%' or nn.na like a.na || '%'))
       or (length(nn.nd) > 6 and a.nd = nn.nd)
),
best as (select c.i, min(c.rank) as r from cand c group by c.i),
pick as (
  select c.i,
    case when count(distinct c.outlet_id) = 1 then min(c.outlet_id)
         when count(distinct c.outlet_id) filter (where c.distributor = r.grp) = 1 then min(c.outlet_id) filter (where c.distributor = r.grp)
    end as outlet_id,
    count(distinct c.outlet_id) as n
  from cand c join best b on b.i = c.i and b.r = c.rank join _ae_rows r on r.i = c.i
  group by c.i
)
select r.*, p.outlet_id,
  case when r.acct is null then 'no account on the sheet'
       when coalesce(r.email, '') !~ '@' then 'no email'
       when p.outlet_id is not null then 'matched'
       when p.n > 1 then 'fits more than one account'
       else 'not in the app' end as how
from _ae_rows r left join pick p on p.i = r.i;

-- One row per account + email (first name given wins).
drop table if exists pg_temp._ae_load;
create temp table _ae_load as
select distinct on (m.outlet_id, lower(trim(m.email)))
  m.outlet_id, nullif(trim(m.name), '') as name, trim(m.email) as email, m.src
from _ae_match m
where m.how = 'matched'
order by m.outlet_id, lower(trim(m.email)), (nullif(trim(m.name), '') is null), m.i;

-- Same person already there with no email → fill the email in.
drop table if exists pg_temp._ae_filled;
create temp table _ae_filled as
with u as (
  update public.sales_account_contacts c
  set email = l.email
  from _ae_load l
  where c.outlet_id = l.outlet_id and l.name is not null
    and lower(trim(c.name)) = lower(l.name)
    and coalesce(trim(c.email), '') = ''
    and not exists (select 1 from public.sales_account_contacts d where d.outlet_id = l.outlet_id and lower(trim(d.email)) = lower(l.email))
  returning c.outlet_id, lower(c.email) as email
)
select * from u;

-- Add the rest that are missing.
drop table if exists pg_temp._ae_added;
create temp table _ae_added as
with ins as (
  select l.outlet_id, l.name, null, null, null, l.email,
    'From FCB Account Emails list (11/24/2026)' || coalesce(' — ' || l.src, ''), 'FCB Account Emails'
  from _ae_load l
  where not exists (select 1 from public.sales_account_contacts c where c.outlet_id = l.outlet_id and lower(trim(c.email)) = lower(l.email))
  returning outlet_id
)
select * from ins;

-- Keep each account's contact count in step (Sales → Accounts list column).
update public.sales_accounts a
set contact_count = (select count(*) from public.sales_account_contacts c where c.outlet_id = a.outlet_id)
where a.outlet_id in (select outlet_id from _ae_added union select outlet_id from _ae_filled);

-- Summary
select
  (select count(*) from _ae_rows) as sheet_rows,
  (select count(*) from _ae_match where how = 'matched') as rows_matched,
  (select count(*) from _ae_added) as contacts_added,
  (select count(*) from _ae_filled) as emails_filled_in,
  (select count(distinct outlet_id) from (select outlet_id from _ae_added union all select outlet_id from _ae_filled) z) as accounts_updated,
  (select count(*) from _ae_match where how = 'no account on the sheet') as rows_no_account,
  (select string_agg(acct || ' (' || coalesce(city, '') || ')', '; ' order by acct) from (select distinct acct, city from _ae_match where how in ('not in the app', 'fits more than one account')) z) as not_matched,
  (select count(*) from public.distributor_contacts) as distributor_contacts;
